//! mu-T and lnf-T solver comparisons against the exact-source library.
//! Generated by tools/rust_port/validate_mut_solve.py.
//! Copyright thermotools and Contributors. Apache-2.0.

#![allow(clippy::excessive_precision)]

use thermopack_rs::{Cubic, CubicKind};

const RTOL: f64 = 1e-6;
const ATOL: f64 = 1e-6;

#[test]
fn lnf_solve_matches_the_source() {
    let mut checked = 0;
    for row in include_str!("fixtures/mut_solve.csv").lines().skip(1) {
        let fields: Vec<_> = row.split(';').collect();
        let case = fields[0];
        let parts: Vec<&str> = case.split('|').collect();
        let components: Vec<&str> = parts[1].split(',').collect();
        let temperature: f64 = parts[2].parse().unwrap();
        let target: Vec<f64> = fields[1].split(',').map(|v| v.parse().unwrap()).collect();
        let guess: Vec<f64> = parts[4].split(',').map(|v| v.parse().unwrap()).collect();
        let expected: Vec<f64> = fields[2].split(',').map(|v| v.parse().unwrap()).collect();
        let model = Cubic::new(CubicKind::PengRobinson, &components).unwrap();
        let solution = thermopack_rs::mut_flash::solve_lnf_t(&model, temperature, &target, &guess)
            .unwrap_or_else(|error| panic!("{case}: {error}"));
        assert_eq!(solution.density.len(), expected.len(), "{case}");
        for (position, (source, native)) in expected.iter().zip(&solution.density).enumerate() {
            let tolerance = ATOL + RTOL * source.abs();
            assert!(
                (source - native).abs() <= tolerance,
                "{case} density {position}: source {source} native {native}"
            );
        }
        checked += 1;
    }
    assert_eq!(checked, 32);
}

#[test]
fn the_log_fugacity_target_is_the_fixed_point() {
    // The original converts a chemical potential specification into a log
    // fugacity specification at the initial guess, so the specification is
    // already satisfied there.
    let model = Cubic::new(CubicKind::PengRobinson, &["C3", "N-H2"]).unwrap();
    let guess = vec![1000.0, 300.0];
    let (fugacity, potential) =
        thermopack_rs::mut_flash::log_fugacity_and_potential(&model, 200.0, &guess).unwrap();
    let solution = thermopack_rs::mut_flash::solve_mu_t(&model, 200.0, &potential, &guess).unwrap();
    for (position, native) in solution.density.iter().enumerate() {
        assert!(
            (native - guess[position]).abs() <= 1e-6 * guess[position].abs().max(1.0),
            "density {position}: {} instead of {}",
            native,
            guess[position]
        );
    }
    // The solved state carries the requested log fugacity.
    let (solved, _) =
        thermopack_rs::mut_flash::log_fugacity_and_potential(&model, 200.0, &solution.density)
            .unwrap();
    for (position, (target, native)) in fugacity.iter().zip(&solved).enumerate() {
        assert!(
            (target - native).abs() <= 1e-6,
            "log fugacity {position}: {target} against {native}"
        );
    }
}

#[test]
fn the_solver_rejects_unusable_specifications() {
    let model = Cubic::new(CubicKind::PengRobinson, &["C3", "N-H2"]).unwrap();
    // A component count mismatch is an error.
    assert!(
        thermopack_rs::mut_flash::solve_lnf_t(&model, 200.0, &[1.0], &[1000.0, 300.0]).is_err()
    );
    assert!(
        thermopack_rs::mut_flash::solve_lnf_t(&model, 200.0, &[f64::NAN, 1.0], &[1000.0, 300.0])
            .is_err()
    );
    // A nonpositive density guess is an error.
    assert!(
        thermopack_rs::mut_flash::solve_lnf_t(&model, 200.0, &[1.0, 2.0], &[0.0, 300.0]).is_err()
    );
    // A nonpositive temperature is an error.
    assert!(
        thermopack_rs::mut_flash::solve_lnf_t(&model, 0.0, &[1.0, 2.0], &[1000.0, 300.0]).is_err()
    );
}
